namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Spaghetti Carbonara", Category = "pasta",
            Ingredients = "Spaghetti\nEggs\nPancetta\nParmesan cheese\nBlack pepper",
            Steps = "1. Cook spaghetti until al dente\n2. Fry pancetta until crispy\n3. Whisk eggs with parmesan\n4. Toss hot pasta with pancetta, then egg mixture\n5. Season with black pepper and serve immediately",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Pad Thai", Category = "pasta",
            Ingredients = "Rice noodles\nShrimp or tofu\nBean sprouts\nPeanuts\nLime\nFish sauce\nTamarind paste",
            Steps = "1. Soak rice noodles in warm water\n2. Stir-fry protein until cooked\n3. Add noodles and sauce (tamarind, fish sauce, sugar)\n4. Toss with bean sprouts\n5. Garnish with peanuts and lime",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Caesar Salad", Category = "salads",
            Ingredients = "Romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nLemon juice\nAnchovy paste",
            Steps = "1. Wash and chop romaine lettuce\n2. Make dressing with anchovy paste, lemon, and parmesan\n3. Toss lettuce with dressing\n4. Top with croutons and shaved parmesan",
            AverageRating = 3.8, RatingCount = 5
        },
        new Recipe
        {
            Id = 4, Title = "Chocolate Lava Cake", Category = "desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 425°F for 12 minutes\n6. Invert onto plate and serve immediately",
            AverageRating = 4.9, RatingCount = 20
        },
        new Recipe
        {
            Id = 5, Title = "Grilled Ribeye Steak", Category = "meat",
            Ingredients = "Ribeye steak\nSalt\nBlack pepper\nGarlic butter\nFresh rosemary",
            Steps = "1. Season steak generously with salt and pepper\n2. Let rest at room temperature for 30 minutes\n3. Grill on high heat, 4 minutes per side for medium-rare\n4. Rest for 5 minutes\n5. Top with garlic butter and rosemary",
            AverageRating = 4.7, RatingCount = 15
        },
        new Recipe
        {
            Id = 6, Title = "Garlic Butter Salmon", Category = "seafood",
            Ingredients = "Salmon fillets\nGarlic\nButter\nLemon\nDill\nSalt and pepper",
            Steps = "1. Season salmon with salt and pepper\n2. Melt butter with minced garlic in a pan\n3. Sear salmon skin-side up for 4 minutes\n4. Flip and cook 3 more minutes\n5. Squeeze lemon over top and garnish with dill",
            AverageRating = 4.4, RatingCount = 10
        },
        new Recipe
        {
            Id = 7, Title = "Vegetable Stir-Fry", Category = "vegetarian",
            Ingredients = "Broccoli\nBell peppers\nSnap peas\nCarrots\nSoy sauce\nGinger\nGarlic\nSesame oil",
            Steps = "1. Cut all vegetables into bite-sized pieces\n2. Heat sesame oil in a wok\n3. Stir-fry garlic and ginger for 30 seconds\n4. Add vegetables, starting with the hardest\n5. Add soy sauce and toss until crisp-tender",
            AverageRating = 4.0, RatingCount = 6
        }
    };

    private int _nextId = 8;

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category == category).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }
}

@page "/categories"
@page "/categories/{CategorySlug}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeShare</PageTitle>

@if (string.IsNullOrEmpty(CategorySlug))
{
    <h1>All Categories</h1>
    <div class="list-group">
        <a href="categories/pasta" class="list-group-item list-group-item-action">🍝 Pasta &amp; Noodles</a>
        <a href="categories/salads" class="list-group-item list-group-item-action">🥗 Salads &amp; Sides</a>
        <a href="categories/desserts" class="list-group-item list-group-item-action">🍰 Desserts</a>
        <a href="categories/meat" class="list-group-item list-group-item-action">🍖 Meat &amp; Poultry</a>
        <a href="categories/seafood" class="list-group-item list-group-item-action">🐟 Seafood</a>
        <a href="categories/vegetarian" class="list-group-item list-group-item-action">🥬 Vegetarian</a>
    </div>
}
else
{
    <h1>@GetCategoryDisplayName(CategorySlug)</h1>
    <a href="categories" class="btn btn-outline-secondary mb-3">&larr; All Categories</a>

    var recipes = RecipeService.GetByCategory(CategorySlug);
    if (recipes.Count == 0)
    {
        <p>No recipes found in this category yet. <a href="submit">Submit one!</a></p>
    }
    else
    {
        <div class="list-group">
            @foreach (var recipe in recipes)
            {
                <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                    <span>@recipe.Title</span>
                    <span class="badge bg-warning text-dark">★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount)</span>
                </a>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategorySlug { get; set; }

    private static string GetCategoryDisplayName(string slug) => slug switch
    {
        "pasta" => "🍝 Pasta & Noodles",
        "salads" => "🥗 Salads & Sides",
        "desserts" => "🍰 Desserts",
        "meat" => "🍖 Meat & Poultry",
        "seafood" => "🐟 Seafood",
        "vegetarian" => "🥬 Vegetarian",
        _ => slug
    };
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="categories">Browse all recipes</a></p>
}
else
{
    <a href="categories/@recipe.Category" class="btn btn-outline-secondary mb-3">&larr; Back to category</a>

    <h1>@recipe.Title</h1>

    <div class="mb-3">
        <span class="text-muted">Average rating: ★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
    </div>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[3..];
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[4..];
            <li>@text.Trim()</li>
        }
    </ol>

    <hr />
    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="recipe.Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="star-rating" role="group" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link fs-3 p-0 me-1 @(star <= selectedRating ? "text-warning" : "text-secondary")"
                @onclick="() => SubmitRating(star)"
                disabled="@submitted"
                aria-label="@star stars">
            @(star <= selectedRating ? "★" : "☆")
        </button>
    }
</div>

@if (submitted)
{
    <div class="alert alert-success mt-2" role="alert">
        Thanks! You rated this recipe @selectedRating star@(selectedRating != 1 ? "s" : "").
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation
@using System.ComponentModel.DataAnnotations

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            <option value="pasta">Pasta & Noodles</option>
            <option value="salads">Salads & Sides</option>
            <option value="desserts">Desserts</option>
            <option value="meat">Meat & Poultry</option>
            <option value="seafood">Seafood</option>
            <option value="vegetarian">Vegetarian</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };

        RecipeService.AddRecipe(recipe);
        successMessage = $"'{model.Title}' submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, MinimumLength = 3)]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

