namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Spaghetti Carbonara", Category = "pasta",
            Ingredients = "Spaghetti\nEggs\nPancetta\nParmesan cheese\nBlack pepper",
            Steps = "1. Cook spaghetti until al dente\n2. Fry pancetta until crispy\n3. Whisk eggs with parmesan\n4. Toss hot pasta with pancetta, then egg mixture\n5. Season with black pepper and serve immediately",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Pad Thai", Category = "pasta",
            Ingredients = "Rice noodles\nShrimp or tofu\nBean sprouts\nPeanuts\nLime\nFish sauce\nTamarind paste",
            Steps = "1. Soak rice noodles in warm water\n2. Stir-fry protein until cooked\n3. Add noodles and sauce (tamarind, fish sauce, sugar)\n4. Toss with bean sprouts\n5. Garnish with peanuts and lime",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Caesar Salad", Category = "salads",
            Ingredients = "Romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nLemon juice\nAnchovy paste",
            Steps = "1. Wash and chop romaine lettuce\n2. Make dressing with anchovy paste, lemon, and parmesan\n3. Toss lettuce with dressing\n4. Top with croutons and shaved parmesan",
            AverageRating = 3.8, RatingCount = 5
        },
        new Recipe
        {
            Id = 4, Title = "Chocolate Lava Cake", Category = "desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 425°F for 12 minutes\n6. Invert onto plate and serve immediately",
            AverageRating = 4.9, RatingCount = 20
        },
        new Recipe
        {
            Id = 5, Title = "Grilled Ribeye Steak", Category = "meat",
            Ingredients = "Ribeye steak\nSalt\nBlack pepper\nGarlic butter\nFresh rosemary",
            Steps = "1. Season steak generously with salt and pepper\n2. Let rest at room temperature for 30 minutes\n3. Grill on high heat, 4 minutes per side for medium-rare\n4. Rest for 5 minutes\n5. Top with garlic butter and rosemary",
            AverageRating = 4.7, RatingCount = 15
        },
        new Recipe
        {
            Id = 6, Title = "Garlic Butter Salmon", Category = "seafood",
            Ingredients = "Salmon fillets\nGarlic\nButter\nLemon\nDill\nSalt and pepper",
            Steps = "1. Season salmon with salt and pepper\n2. Melt butter with minced garlic in a pan\n3. Sear salmon skin-side up for 4 minutes\n4. Flip and cook 3 more minutes\n5. Squeeze lemon over top and garnish with dill",
            AverageRating = 4.4, RatingCount = 10
        },
        new Recipe
        {
            Id = 7, Title = "Vegetable Stir-Fry", Category = "vegetarian",
            Ingredients = "Broccoli\nBell peppers\nSnap peas\nCarrots\nSoy sauce\nGinger\nGarlic\nSesame oil",
            Steps = "1. Cut all vegetables into bite-sized pieces\n2. Heat sesame oil in a wok\n3. Stir-fry garlic and ginger for 30 seconds\n4. Add vegetables, starting with the hardest\n5. Add soy sauce and toss until crisp-tender",
            AverageRating = 4.0, RatingCount = 6
        }
    };

    private int _nextId = 8;

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category == category).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }
}

